// Qualitative results: one expandable row per example, rendered from window.RESULTS
// (results-data.js, generated by tools/build_website_results.py).
//
// Each row shows the input, our generation and the vanilla Wan2.2-14B generation side
// by side -- plus Cosmos3-Super on image-to-video rows, and NEWTON (run with OpenNEWTON,
// the authors' released version) on the two text-to-video rows compared against it --
// and opening it reveals the
// generated keyframes and the expanded prompt. The videos in a row are kept in step,
// and rows off screen are paused.

(function () {
  const data = window.RESULTS;
  if (!data) return;

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function video(src, poster, label) {
    const v = el("video");
    v.muted = true;
    v.loop = true;
    v.playsInline = true;
    v.preload = "metadata";
    v.poster = poster;
    v.setAttribute("aria-label", label);
    const source = el("source");
    source.src = src;
    source.type = "video/mp4";
    v.append(source);
    return v;
  }

  function formatTime(t) {
    return `${Number.isInteger(t) ? t.toFixed(1) : String(t)}s`;
  }

  function inputCell(example) {
    const cell = el("div", "result-cell result-input");
    cell.dataset.label = "Input";
    if (example.input.image) {
      const frame = el("div", "result-frame");
      const img = el("img");
      img.src = example.input.image;
      img.alt = `Input frame: ${example.title}`;
      img.loading = "lazy";
      frame.append(img);
      cell.append(frame, el("p", "result-input-caption", example.input.text));
    } else {
      const card = el("div", "result-frame result-prompt-card");
      card.append(el("p", null, example.input.text));
      cell.append(card);
    }
    return cell;
  }

  function videoCell(label, clip, alt) {
    const cell = el("div", "result-cell");
    cell.dataset.label = label;
    const frame = el("div", "result-frame");
    if (clip) {
      frame.append(video(clip.video, clip.poster, alt));
    } else {
      frame.classList.add("result-placeholder");
      frame.append(el("span", null, `${label} comparison in progress`));
    }
    cell.append(frame);
    return cell;
  }

  function detail(example) {
    const wrap = el("div", "result-detail");

    const kf = el("div", "result-keyframes");
    kf.append(el("h3", "result-detail-title", "Generated keyframes"));
    const strip = el("div", "result-keyframe-strip");
    example.keyframes.forEach((k) => {
      const fig = el("figure", "result-keyframe");
      const img = el("img");
      img.src = k.image;
      img.alt = `Generated keyframe at ${formatTime(k.time)}`;
      img.loading = "lazy";
      const cap = el("figcaption", null, formatTime(k.time));
      if (k.held) cap.append(el("span", "result-keyframe-note", " reused"));
      fig.append(img, cap);
      strip.append(fig);
    });
    kf.append(strip);

    const prompt = el("div", "result-expanded");
    prompt.append(el("h3", "result-detail-title", "Expanded prompt"));
    prompt.append(el("p", null, example.expanded));

    wrap.append(kf, prompt);
    return wrap;
  }

  function row(example) {
    const details = el("details", "result");
    details.id = example.id;
    const summary = el("summary", "result-summary");

    const grid = el("div", "result-grid");
    grid.append(
      inputCell(example),
      videoCell("Ours", example.ours, `Ours: ${example.title}`),
      // image-to-video rows (they carry a Cosmos column) compare against the I2V 14B,
      // text-to-video rows against the T2V 14B
      videoCell("cosmos" in example ? "Wan2.2-14B" : "Wan2.2-T2V-A14B", example.wan,
                `Vanilla Wan2.2: ${example.title}`),
    );
    // Image-to-video rows also compare against Cosmos3-Super; the data carries the key
    // (null while a clip is pending) only where that comparison applies.
    if ("cosmos" in example) {
      grid.classList.add("result-grid-4");
      grid.append(videoCell("Cosmos3-Super", example.cosmos, `Cosmos3-Super: ${example.title}`));
    }
    if ("newton" in example) {
      grid.classList.add("result-grid-4");
      grid.append(videoCell("NEWTON*", example.newton, `NEWTON (OpenNEWTON): ${example.title}`));
    }

    const n = example.keyframes.length;
    const toggle = el("div", "result-toggle");
    toggle.append(
      el("span", "result-chevron"),
      el("span", "result-toggle-text", `Keyframes and expanded prompt`),
      el("span", "result-toggle-count", `${n} keyframe${n === 1 ? "" : "s"}`),
    );

    // a short note under the videos: what the baselines get wrong
    summary.append(grid);
    if (example.note) summary.append(el("p", "result-note", example.note));
    summary.append(toggle);
    details.append(summary, detail(example));
    return details;
  }

  // Keep the videos of a row in step: every comparison follows ours. Clips differ in
  // frame rate (16 fps ours, 24 fps Cosmos) but all run 5 s, so time is the common clock.
  function syncRow(lead, followers) {
    lead.addEventListener("timeupdate", () => {
      followers.forEach((follow) => {
        if (Math.abs(follow.currentTime - lead.currentTime) > 0.12) {
          follow.currentTime = lead.currentTime;
        }
      });
    });
  }

  const visible = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        entry.target.querySelectorAll("video").forEach((v) => {
          if (entry.isIntersecting && !document.hidden) v.play().catch(() => {});
          else v.pause();
        });
      });
    },
    { rootMargin: "120px 0px" },
  );

  document.querySelectorAll("[data-results]").forEach((list) => {
    (data[list.dataset.results] || []).forEach((example) => {
      const node = row(example);
      list.append(node);
      const vids = [...node.querySelectorAll(".result-grid video")];
      if (vids.length > 1) syncRow(vids[0], vids.slice(1));
      visible.observe(node.querySelector(".result-grid"));
    });
  });

  document.addEventListener("visibilitychange", () => {
    document.querySelectorAll(".result-grid").forEach((grid) => {
      const r = grid.getBoundingClientRect();
      const onScreen = r.bottom > 0 && r.top < window.innerHeight;
      grid.querySelectorAll("video").forEach((v) => {
        if (document.hidden || !onScreen) v.pause();
        else v.play().catch(() => {});
      });
    });
  });
})();
